import{_ as s,o as a,c as t,ag as o}from"./chunks/framework.BKVF-9lJ.js";const g=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"concepts.md","filePath":"concepts.md","lastUpdated":1791840224000}'),i={name:"concepts.md"};function n(d,e,r,p,c,h){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>This page defines the vocabulary MFE Forge uses and explains how the CLI derives everything from a project&#39;s directory layout.</p><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><p>A project is a workspace created by <a href="./cli/init"><code>mfe-forge init</code></a>. The CLI always treats the <strong>current working directory</strong> as the project root, so run commands from the directory that contains <code>mfeforge.config.js</code> (or <code>.ts</code>). The layout is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-project/</span></span>
<span class="line"><span>├── apps/                    # hosts and remote apps, grouped by scope</span></span>
<span class="line"><span>│   └── &lt;scope&gt;/</span></span>
<span class="line"><span>│       ├── host/            # the scope&#39;s host (shell)</span></span>
<span class="line"><span>│       └── &lt;name&gt;/          # remote apps</span></span>
<span class="line"><span>├── packages/                # shared packages and libraries</span></span>
<span class="line"><span>├── tools/                   # free for your own scripts</span></span>
<span class="line"><span>├── mfeforge.config.js       # human-authored policy (config)</span></span>
<span class="line"><span>├── mfe-forge.manifest.json  # generated topology (manifest), written by sync/status/migrate</span></span>
<span class="line"><span>├── package.json             # workspaces + root scripts</span></span>
<span class="line"><span>└── tsconfig.base.json</span></span></code></pre></div><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>A <strong>scope</strong> is the first segment of an app name: in <code>shop/catalog</code>, the scope is <code>shop</code>. Scopes model a team, a product area or a domain. Hosts and remote apps <strong>must</strong> be scoped; <code>generate app catalog</code> fails with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Apps and hosts must be scoped: &quot;catalog&quot; → try &quot;catalog-scope/catalog&quot;</span></span></code></pre></div><p>A directory under <code>apps/</code> counts as a scope as soon as one of its subdirectories contains a <code>vite.config.ts</code>.</p><h2 id="host" tabindex="-1">Host <a class="header-anchor" href="#host" aria-label="Permalink to &quot;Host&quot;">​</a></h2><p>A <strong>host</strong> (shell) is the app that composes remotes at runtime. A host is recognised purely by convention: it is the directory <code>apps/&lt;scope&gt;/host</code> with a <code>vite.config.ts</code>. Generate one with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop/host</span></span></code></pre></div><p>Each host only consumes the remotes of its own scope. The host template declares an empty <code>remotes: {}</code> block that <a href="./cli/sync"><code>sync</code></a> fills in, and a <code>src/remotes/declarations.d.ts</code> file that <code>sync</code> regenerates.</p><h2 id="remote" tabindex="-1">Remote <a class="header-anchor" href="#remote" aria-label="Permalink to &quot;Remote&quot;">​</a></h2><p>A <strong>remote</strong> is any other directory <code>apps/&lt;scope&gt;/&lt;name&gt;</code> that contains a <code>vite.config.ts</code>. The app template configures the federation plugin to build a <code>remoteEntry.js</code> that exposes <code>./App</code> (pointing at <code>src/bootstrap.tsx</code>).</p><p>Names derived from <code>shop/catalog</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Derivation</th><th>Example</th></tr></thead><tbody><tr><td>Directory</td><td><code>apps/&lt;scope&gt;/&lt;name&gt;</code></td><td><code>apps/shop/catalog</code></td></tr><tr><td>Federation name</td><td>camelCase of <code>scope/name</code> + <code>App</code></td><td><code>shopCatalogApp</code></td></tr><tr><td>Exposed module</td><td><code>&lt;federationName&gt;/App</code></td><td><code>shopCatalogApp/App</code></td></tr><tr><td>Package name</td><td><code>scope-name</code>, prefixed with <code>@&lt;organization&gt;/</code> when <code>organization</code> is set</td><td><code>shop-catalog</code> or <code>@acme/shop-catalog</code></td></tr><tr><td>Root dev script</td><td><code>dev:&lt;scope&gt;:&lt;name&gt;</code></td><td><code>dev:shop:catalog</code></td></tr><tr><td>Remote URL used by the host</td><td><code>http://localhost:&lt;port&gt;/assets/remoteEntry.js</code></td><td><code>http://localhost:3001/assets/remoteEntry.js</code></td></tr></tbody></table><p>Note that the host is itself discovered as an app too (<code>shop/host</code>, federation name <code>shopHostApp</code>), but it is excluded from its own <code>remotes</code> list.</p><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><p>Each host and remote gets a fixed dev port written into its <code>vite.config.ts</code> (<code>server.port</code> and <code>preview.port</code>) and <code>package.json</code> (<code>vite --port &lt;n&gt;</code>). When you do not pass <code>--port</code>, <code>generate</code> picks the first port in <code>dev.portRange</code> (default <code>[3000, 3999]</code>) that is neither used by another app (literal <code>port: &lt;n&gt;</code> in a <code>vite.config.ts</code>, or <code>--port &lt;n&gt;</code> in a <code>dev</code> script) nor currently bound on your machine.</p><p>Discovery reads the port back from the first <code>port: &lt;number&gt;</code> match in each <code>vite.config.ts</code>. Ports computed at runtime (for example <code>process.env.PORT</code>) are invisible to the CLI; it falls back to <code>3000</code>.</p><h2 id="packages-and-libraries" tabindex="-1">Packages and libraries <a class="header-anchor" href="#packages-and-libraries" aria-label="Permalink to &quot;Packages and libraries&quot;">​</a></h2><p><code>generate package &lt;name&gt;</code> and <code>generate library &lt;name&gt;</code> create workspace packages under <code>packages/&lt;name&gt;</code> (a <code>/</code> in the name becomes <code>-</code>). A <strong>package</strong> exports TypeScript source directly (<code>&quot;main&quot;: &quot;./src/index.ts&quot;</code>); a <strong>library</strong> builds to <code>dist/</code> with <code>tsup</code>. Neither takes part in federation; they are ordinary workspace dependencies. <code>generate design-system</code> creates a Storybook-based component package; see <a href="./design-system">Design system</a>.</p><h2 id="config-versus-manifest" tabindex="-1">Config versus manifest <a class="header-anchor" href="#config-versus-manifest" aria-label="Permalink to &quot;Config versus manifest&quot;">​</a></h2><p>MFE Forge keeps two files with distinct roles (<a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/docs/ai/decisions/0001-manifest-and-config.md" target="_blank" rel="noreferrer">ADR 0001</a>):</p><ul><li><strong><code>mfeforge.config.*</code></strong> is policy you write: organization, default package manager, shared dependency names, port range, build and testing preferences. It is validated with zod on every command. See <a href="./config">Configuration</a>.</li><li><strong><code>mfe-forge.manifest.json</code></strong> is generated topology: <code>version: 1</code>, the project name and root, every discovered app (name, scope, port, URL, federation name, package name, entry), the hosts, the packages under <code>packages/</code> with their dependencies, and an <code>environments</code> object that is currently always empty. <code>sync</code>, <code>status</code> and <code>migrate</code> write it; <code>check</code> and <code>deps</code> read it (or compute it on the fly when it is missing).</li></ul><p>Commit the manifest if you want diffs of topology in code review; regenerate it with <code>mfe-forge sync</code> or <code>mfe-forge status</code>.</p><h2 id="shared-dependencies" tabindex="-1">Shared dependencies <a class="header-anchor" href="#shared-dependencies" aria-label="Permalink to &quot;Shared dependencies&quot;">​</a></h2><p>Federation only works when host and remotes use one copy of React. Every app and host template declares the same <code>shared</code> block:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shared</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  react</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">singleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">requiredVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;^19.1.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;react-dom&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { singleton: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, requiredVersion: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;^19.1.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;react-router-dom&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { singleton: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, requiredVersion: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;^7.5.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  zustand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">singleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">requiredVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;^5.0.12&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p>These versions are hard-coded in the templates. The <code>federation.shared</code> array in the config (default <code>[&#39;react&#39;, &#39;react-dom&#39;, &#39;react-router-dom&#39;]</code>) is <strong>not</strong> written into <code>vite.config.ts</code>; it is used by <a href="./cli/diagnostics"><code>mfe-forge deps</code></a>, which reports a mismatch when packages under <code>packages/</code> declare different versions of a shared dependency. If you upgrade React in one app, upgrade it everywhere and update the <code>requiredVersion</code> values by hand.</p><div class="warning custom-block"><p class="custom-block-title">Share the runtime packages when they carry state</p><p><code>globalEventBus</code> (from <code>@mfe-forge/core</code>) keeps its subscribers in an in-memory <code>Map</code>, and <code>useGlobalStore</code> (from <code>@mfe-forge/store</code>) is a module-level Zustand store. The templates do <strong>not</strong> list <code>@mfe-forge/core</code> or <code>@mfe-forge/store</code> in <code>shared</code>, so by default each remote bundles its own copy and events or global state do not cross the host/remote boundary. Add them as singletons in the host and in every remote when you rely on them for cross-MFE communication:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@mfe-forge/core&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { singleton: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@mfe-forge/store&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { singleton: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span></code></pre></div></div><h2 id="federation-sync" tabindex="-1">Federation sync <a class="header-anchor" href="#federation-sync" aria-label="Permalink to &quot;Federation sync&quot;">​</a></h2><p><code>sync</code> is the operation that turns the filesystem into host configuration:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  apps/ on disk                     discovery                    per host (apps/&lt;scope&gt;/host)</span></span>
<span class="line"><span> ┌──────────────────┐    ┌──────────────────────────┐    ┌──────────────────────────────────┐</span></span>
<span class="line"><span> │ shop/host        │    │ apps:  shop/host  :3000  │    │ vite.config.ts                   │</span></span>
<span class="line"><span> │ shop/catalog     │ -&gt; │        shop/catalog :3001│ -&gt; │   remotes: { shopCatalogApp: …,  │</span></span>
<span class="line"><span> │ shop/cart        │    │        shop/cart    :3002│    │              shopCartApp: … }    │</span></span>
<span class="line"><span> │ admin/host       │    │ hosts: shop/host,        │    │ src/remotes/declarations.d.ts    │</span></span>
<span class="line"><span> └──────────────────┘    │        admin/host        │    │   declare module &#39;shopCartApp/App&#39;│</span></span>
<span class="line"><span>                         └──────────────────────────┘    └──────────────────────────────────┘</span></span>
<span class="line"><span>                                                          + mfe-forge.manifest.json (root)</span></span></code></pre></div><p>The <code>remotes: { ... }</code> block is located with a regular expression and replaced entirely, so any hand-written entries in it are overwritten. When the block is missing, <code>sync</code> prints a warning and leaves the file alone. <code>generate app</code> and <code>generate host</code> perform the same update for the affected host. Run <code>mfe-forge sync --check</code> in CI to fail when a host is out of date.</p><h2 id="runtime-loading" tabindex="-1">Runtime loading <a class="header-anchor" href="#runtime-loading" aria-label="Permalink to &quot;Runtime loading&quot;">​</a></h2><p>In the host, a remote is loaded through a dynamic import of its exposed module:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { LazyRemote } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@mfe-forge/core&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Catalog</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LazyRemote</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;shopCatalogApp/App&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), { remoteName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;shop/catalog&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &lt;Route path=&quot;/catalog/*&quot; element={&lt;Catalog /&gt;} /&gt;</span></span></code></pre></div><p><code>LazyRemote</code> wraps <code>React.lazy</code> in an <code>MFErrorBoundary</code> and a <code>Suspense</code> fallback. If the remote fails to load, the boundary renders an alert with a <strong>Try again</strong> button, and retrying creates a fresh lazy import (a rejected <code>React.lazy</code> never retries by itself). <code>RemoteLoader</code> offers the same behaviour as a component keyed by remote name and keeps an LRU cache of at most 100 lazy components. Cross-MFE communication uses the <code>EventBus</code> from <code>@mfe-forge/core</code> and the stores from <code>@mfe-forge/store</code>. See <a href="./packages/core"><code>@mfe-forge/core</code></a> and <a href="./packages/store"><code>@mfe-forge/store</code></a>.</p>`,40)])])}const k=s(i,[["render",n]]);export{g as __pageData,k as default};
